def _str_to_replace(buf):
    buf = buf.replace('None', 'null')
    buf = buf.replace('False', 'false')
    buf = buf.replace('True', 'true')
    buf = buf.replace('"', '')
    buf = buf.replace("'", '"')
    return buf
def _str_to_list(buf):
    buf_list = []
    if len(buf) == 2:
        return buf_list
    else:
        buf = _str_to_replace(buf)
        buf = json.loads(buf)
        return buf
