def creat_sheet3(sheet, data, countrow, business_type='stock'):
    if len(data['columns']) == 0 or len(data['index']) == 0 or len(data['data']) == 0:
        return countrow
    else:
        columns = data['columns']
        positions_index = columns.index('positions')
        row = countrow
        if row == 0:
            if business_type == 'stock':
                sheet.write(row, 0, '日期')
                sheet.write(row, 1, '股票')
                sheet.write(row, 2, '收盘价（元）')
                sheet.write(row, 3, '持仓数量')
                sheet.write(row, 4, '证券市值（元）')
                sheet.write(row, 5, '收益（元）')
                row += 1
            elif business_type == 'future':
                sheet.write(row, 0, '日期')
                sheet.write(row, 1, '合约代码')
                sheet.write(row, 2, '方向')
                sheet.write(row, 3, '收盘价（元）')
                sheet.write(row, 4, '持仓数量')
                sheet.write(row, 5, '市值（元）')
                sheet.write(row, 6, '占用保证金（元）')
                sheet.write(row, 7, '收益（元）')
                row += 1
        if business_type == 'stock':
            for i in range(len(data['index'])):
                utctime = data['index'][i][:10]
                if len(data['data'][i][positions_index]) != 0:
                    for j in range(len(data['data'][i][positions_index])):
                        positions = data['data'][i][positions_index][j]
                        sheet.write(row, 0, utctime)
                        sheet.write(row, 1, positions['symbol'])
                        sheet.write(row, 2, float('%.2f' % positions['last_sale_price']))
                        sheet.write(row, 3, positions['amount'])
                        sheet.write(row, 4, float('%.2f' % (positions['amount'] * positions['last_sale_price'])))
                        sheet.write(row, 5, float('%.2f' % (positions['amount'] * (positions['last_sale_price'] - positions['cost_basis']))))
                        row += 1
        elif business_type == 'future':
            for i in range(len(data['index'])):
                utctime = data['index'][i][:10]
                if len(data['data'][i][positions_index]) != 0:
                    for j in range(len(data['data'][i][positions_index])):
                        positions = data['data'][i][positions_index][j]
                        sheet.write(row, 0, utctime)
                        sheet.write(row, 1, positions['symbol'])
                        if positions['long_amount'] > 0:
                            sheet.write(row, 2, '多')
                            sheet.write(row, 3, float('%.2f' % positions['long_price']))
                            sheet.write(row, 4, positions['long_amount'])
                            position_price = positions['amount'] * positions['last_sale_price'] * positions['contract_multiplier']
                            sheet.write(row, 5, float('%.2f' % position_price))
                            sheet.write(row, 6, float('%.2f' % (position_price * positions['margin_rate'])))
                            if 'long_pnl' in positions.keys():
                                sheet.write(row, 7, float('%.2f' % positions['long_pnl']))
                            else:
                                sheet.write(row, 7, float('%.2f' % (position_price - positions['long_cost_basis'] * positions['amount'] * positions['contract_multiplier'])))
                            row += 1
                        if positions['short_amount'] > 0:
                            sheet.write(row, 2, '空')
                            sheet.write(row, 3, float('%.2f' % positions['short_price']))
                            sheet.write(row, 4, positions['short_amount'])
                            position_price = positions['short_amount'] * positions['short_price'] * positions['contract_multiplier']
                            sheet.write(row, 5, float('%.2f' % position_price))
                            sheet.write(row, 6, float('%.2f' % (position_price * positions['margin_rate'])))
                            if 'short_pnl' in positions.keys():
                                sheet.write(row, 7, float('%.2f' % positions['short_pnl']))
                            else:
                                sheet.write(row, 7, float('%.2f' % (position_price - positions['short_cost_basis'] * positions['amount'] * positions['contract_multiplier'])))
                            row += 1
        return row
def backtest_download_result(user_id, backtest_id, business_type):
    try:
        book = xlwt.Workbook(encoding='utf-8')
        countrow_sheet1, countrow_sheet2, countrow_sheet3 = [0, 0, 0]
        sheet1 = book.add_sheet('收益概述', cell_overwrite_ok=True)
        sheet2 = book.add_sheet('交易详情', cell_overwrite_ok=True)
        sheet3 = book.add_sheet('每日持仓&收益', cell_overwrite_ok=True)
        file_path = os.path.join(BACKTEST_DIR_PATH, user_id, backtest_id, 'testds_to_json.csv')
        if os.path.exists(file_path):
            df = pd.read_csv(file_path, index_col=0)
            if len(df) > 1:
                df = df[:-1]
            while len(df) > 1 and list(df[-1:].index)[0] == END_TIMESTAMP:
                df = df[:-1]
                if len(df) > 1:
                    break
        else:
            system_log.warning('testds_to_json.csv文件不存在')
    except BaseException:
        system_log.error(f'用户{user_id!s}回测{backtest_id!s}文件下载失败，错误原因：{get_traceback_message()!s}')
        return False
